async function inflateBase64(path){const response=await fetch(path,{cache:"no-store"});if(!response.ok)throw new Error(`Unable to load ${path}: ${response.status}`);const base64=(await response.text()).trim();const compressed=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));if(!("DecompressionStream" in globalThis))throw new Error("This browser needs gzip DecompressionStream support.");const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream("gzip"));return new Response(stream).text()}async function boot(){const status=document.querySelector("#status");try{if(status)status.textContent="Loading verified chess engine…";const[engineSource,appSource]=await Promise.all([inflateBase64("./assets/engine.js.gz.b64"),inflateBase64("./assets/app.js.gz.b64")]);const engineUrl=URL.createObjectURL(new Blob([engineSource],{type:"text/javascript"}));const patchedApp=appSource.replaceAll("./engine.js",engineUrl);const appUrl=URL.createObjectURL(new Blob([patchedApp],{type:"text/javascript"}));await import(appUrl)}catch(error){console.error(error);if(status)status.textContent="Startup failed";const sub=document.querySelector("#substatus");if(sub)sub.textContent=error instanceof Error?error.message:String(error)}}void boot();